mapper.select:
SELECT a.*, p.name AS pet_name, p.image_url AS pet_image_url, u.nickname AS applicant_name, r.nickname AS reviewer_name FROM adoption_application a LEFT JOIN pet p ON a.pet_id = p.id LEFT JOIN sys_user u ON a.applicant_id = u.id LEFT JOIN sys_user r ON a.reviewer_id = r.id
AND a.status = #{status}
AND a.applicant_id = #{applicantId}
AND a.pet_id = #{petId}
AND p.publisher_id = #{publisherId}
ORDER BY a.create_time DESC
